 * The tree the parser builds. Every node carries a `t` tag naming its kind:
 * `table`, `arrayOfTables`, `array`, `string`, `integer`, `float` or `boolean`.
 * Tables hold their children in a Map so key order never leaks in from
 * insertion order; every place that walks a table's keys sorts them first.
 */
import { ParseError } from './parseError.js'

export function newTable() {
  return { t: 'table', map: new Map(), headerClosed: false }
}

export function newArrayOfTables() {
  return { t: 'arrayOfTables', items: [] }
}

export function newArray() {
  return { t: 'array', items: [] }
}

/** Compares strings by ascending Unicode code point, not UTF-16 code unit. */
export function compareCodePoint(a, b) {
  const ac = Array.from(a)
  const bc = Array.from(b)
  const len = Math.min(ac.length, bc.length)
  for (let i = 0; i < len; i++) {
    const ca = ac[i].codePointAt(0)
    const cb = bc[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ac.length - bc.length
}

function pathText(segments) {
  return segments.join('.')
}

/**
 * Walks `segments` under `startNode`, creating tables along the way and
 * descending into the last element of any array of tables it meets, then
 * assigns `value` at the final segment. `basePath` is the full path from the
 * document root to `startNode`, used only to phrase error messages.
 */
export function assignPath(startNode, segments, value, basePath, lineNo) {
  let cursor = startNode
  const pathSoFar = [...basePath]
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    pathSoFar.push(seg)
    let child = cursor.map.get(seg)
    if (!child) {
      child = newTable()
      cursor.map.set(seg, child)
    }
    if (child.t === 'table') {
      cursor = child
    } else if (child.t === 'arrayOfTables') {
      cursor = child.items[child.items.length - 1]
    } else {
      throw new ParseError(lineNo, `${pathText(pathSoFar)} is not a table`)
    }
  }
  const last = segments[segments.length - 1]
  pathSoFar.push(last)
  if (cursor.map.has(last)) {
    throw new ParseError(lineNo, `key ${pathText(pathSoFar)} is defined twice`)
  }
  cursor.map.set(last, value)
}

/** Handles a `[name]` or `[[name]]` header, updating the document's cursor. */
export function processHeader(doc, segments, isArray, lineNo) {
  let cursor = doc.root
  const pathSoFar = []
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    pathSoFar.push(seg)
    let child = cursor.map.get(seg)
    if (!child) {
      child = newTable()
      cursor.map.set(seg, child)
    }
    if (child.t === 'table') {
      cursor = child
    } else if (child.t === 'arrayOfTables') {
      cursor = child.items[child.items.length - 1]
    } else {
      throw new ParseError(lineNo, `${pathText(pathSoFar)} is not a table`)
    }
  }
  const last = segments[segments.length - 1]
  pathSoFar.push(last)
  let child = cursor.map.get(last)
  if (!isArray) {
    if (!child) {
      child = newTable()
      child.headerClosed = true
      cursor.map.set(last, child)
    } else if (child.t === 'table') {
      if (child.headerClosed) {
        throw new ParseError(lineNo, `table ${pathText(pathSoFar)} is defined twice`)
      }
      child.headerClosed = true
    } else {
      throw new ParseError(lineNo, `${pathText(pathSoFar)} is not a table`)
    }
    doc.current = child
    doc.currentPath = pathSoFar
  } else {
    if (!child) {
      child = newArrayOfTables()
      cursor.map.set(last, child)
    } else if (child.t !== 'arrayOfTables') {
      throw new ParseError(lineNo, `${pathText(pathSoFar)} is not an array of tables`)
    }
    const table = newTable()
    child.items.push(table)
    doc.current = table
    doc.currentPath = pathSoFar
  }
}
"}

