{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-aJyE7r/src/scanner.js","content":"/**
 * Character-level scanning shared by header lines, key lines and values.
 * A scan context is `{ line, pos, lineNo }`; every function here advances
 * `ctx.pos` and throws `ParseError` on malformed input.
 */
import { ParseError } from './parseError.js'

const NAME_CHAR = /[A-Za-z0-9_-]/

function fail(ctx, reason) {
  throw new ParseError(ctx.lineNo, reason)
}

export function skipSpaces(ctx) {
  while (ctx.pos < ctx.line.length && (ctx.line[ctx.pos] === ' ' || ctx.line[ctx.pos] === '\t')) {
    ctx.pos++
  }
}

/**
 * Skips spaces and tabs, then returns the next meaningful character without
 * consuming it, or undefined if the line has ended. A `#` or `;` reached here
 * (not glued to a bareword already being scanned) starts a comment, so it is
 * reported the same as reaching the end of the line.
 */
export function peekSignificant(ctx) {
  skipSpaces(ctx)
  if (ctx.pos >= ctx.line.length) return undefined
  const c = ctx.line[ctx.pos]
  if (c === '#' || c === ';') return undefined
  return c
}

/** Requires the line to hold nothing more than trailing space or a comment. */
export function expectLineEnd(ctx, reason) {
  skipSpaces(ctx)
  if (ctx.pos >= ctx.line.length) return
  const c = ctx.line[ctx.pos]
  if (c === '#' || c === ';') return
  fail(ctx, reason)
}

export function parseName(ctx) {
  const c = peekSignificant(ctx)
  if (c === undefined) fail(ctx, 'expected a name')
  if (c === '"') return parseBasicString(ctx).v
  if (c === "'") return parseLiteralString(ctx).v
  if (NAME_CHAR.test(c)) {
    const start = ctx.pos
    while (ctx.pos < ctx.line.length && NAME_CHAR.test(ctx.line[ctx.pos])) ctx.pos++
    return ctx.line.slice(start, ctx.pos)
  }
  fail(ctx, 'expected a name')
}

export function parseDottedName(ctx) {
  const parts = [parseName(ctx)]
  while (peekSignificant(ctx) === '.') {
    ctx.pos++
    parts.push(parseName(ctx))
  }
  return parts
}

const ESCAPES = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }

export function parseBasicString(ctx) {
  ctx.pos++ // opening quote
  let out = ''
  while (true) {
    if (ctx.pos >= ctx.line.length) fail(ctx, 'unterminated string')
    const ch = ctx.line[ctx.pos]
    if (ch === '"') {
      ctx.pos++
      return { t: 'string', v: out }
    }
    if (ch === '\\') {
      ctx.pos++
      if (ctx.pos >= ctx.line.length) fail(ctx, 'unterminated string')
      const esc = ctx.line[ctx.pos]
      if (esc === 'u') {
        const hex = ctx.line.slice(ctx.pos + 1, ctx.pos + 5)
        if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
          out += String.fromCharCode(parseInt(hex, 16))
          ctx.pos += 5
        } else {
          fail(ctx, 'invalid escape \\u')
        }
      } else if (Object.prototype.hasOwnProperty.call(ESCAPES, esc)) {
        out += ESCAPES[esc]
        ctx.pos++
      } else {
        fail(ctx, `invalid escape \\${esc}`)
      }
    } else {
      out += ch
      ctx.pos++
    }
  }
}

export function parseLiteralString(ctx) {
  ctx.pos++ // opening quote
  const start = ctx.pos
  while (true) {
    if (ctx.pos >= ctx.line.length) fail(ctx, 'unterminated string')
    if (ctx.line[ctx.pos] === "'") {
      const out = ctx.line.slice(start, ctx.pos)
      ctx.pos++
      return { t: 'string', v: out }
    }
    ctx.pos++
  }
}

const INTEGER_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

/** Reads a run of non-delimiter text and classifies it as a value. */
export function parseBareword(ctx) {
  const start = ctx.pos
  while (ctx.pos < ctx.line.length) {
    const ch = ctx.line[ctx.pos]
    if (ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}') break
    ctx.pos++
  }
  const text = ctx.line.slice(start, ctx.pos)
  if (text === 'true') return { t: 'boolean', v: true }
  if (text === 'false') return { t: 'boolean', v: false }
  if (INTEGER_RE.test(text)) {
    return { t: 'integer', v: BigInt(text.replace(/_/g, '')) }
  }
  if (FLOAT_RE.test(text) && /[.eE]/.test(text)) {
    return { t: 'float', v: Number(text.replace(/_/g, '')) }
  }
  fail(ctx, `invalid value ${text}`)
}

export function fatal(ctx, reason) {
  fail(ctx, reason)
}
"}

