    }
    case 'arrayOfTables':
    case 'array': {
      if (node.items.length === 0) return '[]'
      const parts = node.items.map((it) => pad1 + stringifyNode(it, depth + 1))
      return `[\n${parts.join(',\n')}\n${pad}]`
    }
    case 'string':
      return JSON.stringify(node.v)
    case 'boolean':
      return node.v ? 'true' : 'false'
    case 'integer':
