/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { parseDocument } from './document.js'
import { toJSON, toKeys } from './format.js'
import { ParseError } from './parseError.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  // eslint-disable-next-line no-constant-condition
  while (true) {
    let n
    try {
      n = require('node:fs').readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (n === 0) break
    chunks.push(Buffer.from(buf.subarray(0, n)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }

  const input = readStdin()

  let root
  try {
    root = parseDocument(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: line ${err.lineNo}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  process.stdout.write(mode === 'json' ? toJSON(root) : toKeys(root))
  process.exit(0)
}

main()
"}

